/**
 * Ids, tokens and hashing (ARCHITECTURE §6, §7).
 *
 * Ids are generated by the *client* and only validated here — the server's job is to reject
 * anything that is not a 22-char base62 id and to refuse duplicates with 409.
 */

/** 22-char base62, from 128 client-side random bits (ARCHITECTURE §6). */
export const ID_CHARS = 22;
const ID_PATTERN = /^[0-9A-Za-z]{22}$/;

/** Delete tokens and device tokens: 32 random bytes, base64url (ARCHITECTURE §7). */
export const TOKEN_BYTES = 32;

export function isValidId(id: string): boolean {
  return ID_PATTERN.test(id);
}

export function toBase64Url(bytes: Uint8Array): string {
  const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
  let out = "";

  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i]!;
    const b = bytes[i + 1];
    const c = bytes[i + 2];

    out += ALPHABET[a >> 2];
    out += ALPHABET[((a & 0x03) << 4) | ((b ?? 0) >> 4)];
    if (b === undefined) break;
    out += ALPHABET[((b & 0x0f) << 2) | ((c ?? 0) >> 6)];
    if (c === undefined) break;
    out += ALPHABET[c & 0x3f];
  }

  return out;
}

/** A fresh bearer token. */
export function newToken(): string {
  return toBase64Url(crypto.getRandomValues(new Uint8Array(TOKEN_BYTES)));
}

/**
 * SHA-256, hex. Tokens are only ever stored hashed (ARCHITECTURE §7), so a database dump
 * cannot be replayed against the API.
 */
export async function sha256Hex(value: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

/**
 * Compare two hex digests without leaking where they diverge.
 *
 * A delete token is a bearer credential, so an early-exit `===` would let a caller recover
 * it byte by byte from response timings.
 */
export function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

/** R2 key for a drop (ARCHITECTURE §7.8). */
export function dropKey(id: string): string {
  return `d/${id}`;
}

/** R2 key for a vault item (ARCHITECTURE §7.8). */
export function itemKey(vaultId: string, itemId: string): string {
  return `v/${vaultId}/${itemId}`;
}
